package com.smarthub.plus;
import android.os.Bundle;
import android.graphics.*;
import android.widget.*;
import java.util.concurrent.*;
import org.json.*;
/** Uses the already verified EPG identity, without re-searching a different film. */
public final class ArtworkDetailsActivity extends HubActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private boolean closed;
 @Override public void onCreate(Bundle b){super.onCreate(b);try{JSONObject item=new JSONObject(prefs().getString("community_current_work","{}"));LinearLayout body=page(item.optString("title",tx("تفاصيل العمل","Title details")));note(body,item.optString("release")+" · "+item.optString("runtime")+" · "+item.optString("genres"));note(body,item.optString("summary"));String background=item.optString("background");if(!background.isEmpty()){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(image,new LinearLayout.LayoutParams(-1,dp(230)));load(image,background,1600);}note(body,tx("إخراج: ","Directors: ")+item.optString("directors"));JSONArray people=item.optJSONArray("people");if(people!=null&&people.length()>0){body.addView(text(tx("الممثلون","Cast"),22,true));android.widget.HorizontalScrollView scroll=new android.widget.HorizontalScrollView(this);LinearLayout row=row();scroll.addView(row);body.addView(scroll);for(int n=0;n<Math.min(8,people.length());n++){JSONObject person=people.getJSONObject(n);LinearLayout card=col();card.setPadding(dp(8),0,dp(8),0);ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(photo,new LinearLayout.LayoutParams(dp(105),dp(145)));card.addView(text(person.optString("name"),14,true));card.addView(text(person.optString("role"),12,false));row.addView(card,new LinearLayout.LayoutParams(dp(145),-2));load(photo,person.optString("photo"),350);}}else note(body,tx("الممثلون: ","Cast: ")+item.optString("cast"));note(body,"This product uses the TMDB API but is not endorsed or certified by TMDB.");}catch(Exception e){page(tx("تفاصيل غير متاحة؛ اختر عملاً مطابقاً أولاً","Details unavailable; select a matching title first"));}}
 private void load(ImageView image,String address,int max){io.execute(()->{try{java.net.URI uri=new java.net.URI(address);if(!"https".equals(uri.getScheme())||!"image.tmdb.org".equals(uri.getHost())||uri.getUserInfo()!=null)return;byte[] bytes=ArtworkCache.fetch(this,uri.toURL(),8*1024*1024);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth>10000||o.outHeight>10000)return;o.inSampleSize=1;while(o.outWidth/o.inSampleSize>max*2||o.outHeight/o.inSampleSize>max*2)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);runOnUiThread(()->{if(!closed)image.setImageBitmap(bitmap);});}catch(Exception ignored){}});}
 @Override protected void onDestroy(){closed=true;io.shutdownNow();super.onDestroy();}
}
